"""§1.4 B completion, selected source pairs. Import has no file-system writes."""
from common import *
lessons=[]
def add(*a,**kw):lessons.append(card(*a,**kw))
def vadd(a,b):return tuple(x+y for x,y in zip(a,b))
def sub(a,b):return tuple(x-y for x,y in zip(a,b))
def mul(a,k):return tuple(x*k for x in a)
def lerp(a,b,t):return vadd(a,mul(sub(b,a),t))
def length(a,b):return math.dist(a,b)
def foot(p,a,b):
 v=sub(b,a);return vadd(a,mul(v,sum(x*y for x,y in zip(sub(p,a),v))/sum(x*x for x in v)))
def scene(points,extra=(),given=(),views=None,grid=False):
 p=dict(points);edges=[['A','B'],['B','C'],['C','A']]+[list(e) for e in extra]
 if grid:
  xy=list(p.values());xmin=math.floor(min(v[0] for v in xy))-1;xmax=math.ceil(max(v[0] for v in xy))+1;ymin=math.floor(min(v[1] for v in xy))-1;ymax=math.ceil(max(v[1] for v in xy))+1
  for x in range(xmin,xmax+1):
   p[f'_gx{x}a']=(x,ymin);p[f'_gx{x}b']=(x,ymax);edges.append([f'_gx{x}a',f'_gx{x}b'])
  for y in range(ymin,ymax+1):
   p[f'_gy{y}a']=(xmin,y);p[f'_gy{y}b']=(xmax,y);edges.append([f'_gy{y}a',f'_gy{y}b'])
 names=['A','B','C']+list(given)
 m=model(p,edges,names,{'neutral':{'label':'Данные условия'+(' на сетке с шагом 1' if grid else ''),'points':list(given)},'focus':{'label':'Треугольник ABC','polygon':['A','B','C']},**(views or {})})
 if grid:m['views']['neutral']['segments']=[['A','B'],['B','C'],['C','A']]
 return m
def emit(n,part,page,title,text,goal,answer,hint,steps,m,caption=None):
 answers=answer if isinstance(answer,list) else [answer]
 args={} if caption is None else {'caption':caption}
 add('1.4','B',n,part,page,title,text,goal,str(answers[0]),hint,steps,m,**args)
 lessons[-1]['answer']['accepted']=list(dict.fromkeys(s for a in answers for s in acc(a)))
def area_view(names,label):return {'label':label,'polygon':names}
REP='Размеры, не заданные в условии, выбраны для одного допустимого треугольника. Решение не зависит от его формы.'

