for part,a,b,at,bt,ans in [('a',math.sqrt(7),3*math.sqrt(7),'√7','3√7',7),('b',4*math.sqrt(3),8*math.sqrt(3),'4√3','8√3',12)]:
 p={'C':(0,0),'B':(a,0),'A':(b/2,b*math.sqrt(3)/2),'_ext':(-a*.45,0)}
