 squares='7+63−2·√7·3√7·1/2=49' if part=='a' else '48+192−2·4√3·8√3·1/2=144'
 emit(1,part,21,'Сторона по внешнему углу',f'В треугольнике ABC BC={at}, AC={bt}, внешний угол при C равен 120°. Найди AB.','Найди длину AB.',ans,'Сначала найди внутренний угол C.',[
  step('Внутренний угол','∠ACB=180°−120°=60°.','Внутренний угол и смежный с ним внешний угол в сумме дают180°.','angle'),
  step('Теорема косинусов',f'AB²=BC²+AC²−2·BC·AC·cos60°={squares}.','Теорема косинусов для стороны напротив угла C; cos60°=1/2.'),
  step('Длина стороны',f'AB=√{ans*ans}={ans}.','Длина положительна, поэтому берём положительный квадратный корень.')],m)

