# Keep running text readable beside formulas without altering symbolic notation.
import re
def _space_text(x):
 if isinstance(x,str):return re.sub(r'(?<=[А-Яа-яЁё])(?=\d)',' ',x)
 if isinstance(x,list):return [_space_text(v) for v in x]
 if isinstance(x,dict):return {k:_space_text(v) for k,v in x.items()}
 return x
lessons=[_space_text(c) for c in lessons]
